		float prevYaw = this.rotationYaw;
		float prevPitch = this.rotationPitch;
		this.readFromNBT(nbt);
		this.setLocationAndAngles(prevX, prevY, prevZ, prevYaw, prevPitch);
		if(!this.isEntityAlive()) {
