package thebetweenlands.common.tile;

import javax.annotation.Nonnull;
import javax.annotation.Nullable;

import mcp.MethodsReturnNonnullByDefault;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.network.NetworkManager;
import net.minecraft.network.play.server.SPacketUpdateTileEntity;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.ITickable;
import net.minecraft.util.NonNullList;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.items.ItemStackHandler;
import thebetweenlands.api.recipes.ICompostBinRecipe;
import thebetweenlands.common.item.misc.ItemMisc.EnumItemMisc;
import thebetweenlands.common.recipe.misc.CompostRecipe;

public class TileEntityCompostBin extends TileEntityBasicInventory implements ITickable {
    public static final int COMPOST_PER_ITEM = 25;
    public static final int MAX_COMPOST_AMOUNT = COMPOST_PER_ITEM * 16;
    public static final int MAX_ITEMS = 20;

    public static final float MAX_OPEN = 90f;
    public static final float MIN_OPEN = 0f;
    public static final float OPEN_SPEED = 10f;
    public static final float CLOSE_SPEED = 10f;

    private int compostedAmount;
    private int totalCompostAmount;
    private boolean open = false;
    private float lidAngle = 0.0f;
    private int[] processes = new int[MAX_ITEMS];
    private int[] compostAmounts = new int[MAX_ITEMS];
    private int[] compostTimes = new int[MAX_ITEMS];

    public TileEntityCompostBin() {
        super("container.bl.compost_bin", NonNullList.withSize(MAX_ITEMS, ItemStack.EMPTY), (te, inv) -> new ItemStackHandler(inv) {
            @Override
            public void setSize(int size) {
                this.stacks = te.inventory = NonNullList.withSize(MAX_ITEMS, ItemStack.EMPTY);
            }

            @Override
            protected void onContentsChanged(int slot) {
                // Don't mark dirty while loading chunk!
                if(te.hasWorld()) {
                    te.markDirty();
                }
            }

            @Override
            public int getSlotLimit(int slot) {
                return 1;
            }
        });
    }


    public static int[] readIntArrayFixedSize(String id, int length, NBTTagCompound compound) {
        int[] array = compound.getIntArray(id);
        return array.length != length ? new int[length] : array;
    }

    /**
     * Sets whether the lid is closed
     *
     * @return
     */
    public boolean isOpen() {
        return this.open;
    }

    /**
     * Sets whether the lid is open
     *
     * @param open
     */
    public void setOpen(boolean open) {
        this.open = open;
    }

    @Override
    public void update() {
        this.lidAngle = this.open ? Math.min(this.lidAngle + OPEN_SPEED, MAX_OPEN) : Math.max(this.lidAngle - CLOSE_SPEED, MIN_OPEN);

        if (!this.world.isRemote) {
            if (!this.open) {
                for (int i = 0; i < this.inventory.size(); i++) {
                    if (!this.getStackInSlot(i).isEmpty()) {
                        if (this.processes[i] >= this.compostTimes[i]) {
                            this.compostedAmount += this.compostAmounts[i];
                            super.setInventorySlotContents(i, ItemStack.EMPTY);
                            this.processes[i] = 0;
                            this.compostTimes[i] = 0;
                            this.compostAmounts[i] = 0;

                            this.world.notifyBlockUpdate(this.pos, this.world.getBlockState(this.pos), this.world.getBlockState(this.pos), 2);
                        } else {
                            this.processes[i]++;
                        }
                    }
                }
            }

            // Fall down
            for (int i = 1; i < this.inventory.size(); i++) {
                if (this.getStackInSlot(i - 1).isEmpty() && !this.getStackInSlot(i).isEmpty()) {
                    this.setInventorySlotContents(i - 1, getStackInSlot(i));
                    this.setInventorySlotContents(i, ItemStack.EMPTY);
                    this.processes[i - 1] = this.processes[i];
                    this.processes[i] = 0;
                    this.compostAmounts[i - 1] = this.compostAmounts[i];
                    this.compostAmounts[i] = 0;
                    this.compostTimes[i - 1] = this.compostTimes[i];
                    this.compostTimes[i] = 0;
                }
            }
        }
    }

    /**
     * Removes the specified amount of compost and returns true if successful
     *
     * @param amount
     * @return
     */
    public boolean removeCompost(int amount) {
        if (this.compostedAmount != 0) {
            if (this.compostedAmount >= amount) {
                this.compostedAmount -= amount;
                this.totalCompostAmount -= amount;
            } else {
                this.compostedAmount = 0;
                this.totalCompostAmount = 0;
            }
            this.world.notifyBlockUpdate(this.pos, this.world.getBlockState(this.pos), this.world.getBlockState(this.pos), 2);
            this.markDirty();
            return true;
        }
        return false;
    }

    /**
     * Adds an item to the compost bin
     *
     * @param stack
     * @param compostAmount
     * @param compostTime
     * @param doSimulate
     * @return
     */
    public int addItemToBin(ItemStack stack, int compostAmount, int compostTime, boolean doSimulate) {
        int clampedAmount = this.getTotalCompostAmount() + compostAmount <= MAX_COMPOST_AMOUNT ? compostAmount : MAX_COMPOST_AMOUNT - this.getTotalCompostAmount();
        if (clampedAmount > 0) {
            for (int i = 0; i < this.inventory.size(); i++) {
                if (this.getStackInSlot(i).isEmpty()) {
                    if (!doSimulate) {
                        ItemStack copy = stack.copy();
                        copy.setCount(1);
                        super.setInventorySlotContents(i, copy);
                        this.compostAmounts[i] = clampedAmount;
                        this.compostTimes[i] = compostTime;
                        this.processes[i] = 0;
                        this.totalCompostAmount += clampedAmount;

                        this.world.notifyBlockUpdate(this.pos, this.world.getBlockState(this.pos), this.world.getBlockState(this.pos), 2);
                    }
                    return 1;
                }
            }
            return 0;
        }
        return -1;
    }

    private boolean canAddItemToBin(int compostAmount, int index) {
        return this.inventory.get(index).isEmpty() && (this.getTotalCompostAmount() + compostAmount <= MAX_COMPOST_AMOUNT ? compostAmount : MAX_COMPOST_AMOUNT - this.getTotalCompostAmount()) > 0;
    }

    @Override
    public void readFromNBT(NBTTagCompound nbt) {
        if (nbt.hasKey("Items", Constants.NBT.TAG_INT_ARRAY)) { // To update from the old keys
            nbt.setIntArray("Inventory", nbt.getIntArray("Items"));
        }
        super.readFromNBT(nbt);
        this.processes = readIntArrayFixedSize("Processes", inventory.size(), nbt);
        this.compostAmounts = readIntArrayFixedSize("CompostAmounts", inventory.size(), nbt);
        this.compostTimes = readIntArrayFixedSize("CompostTimes", inventory.size(), nbt);
        this.totalCompostAmount = nbt.getInteger("TotalCompostAmount");
        this.compostedAmount = nbt.getInteger("CompostedAmount");
        this.open = nbt.getBoolean("Open");
        this.lidAngle = nbt.getFloat("LidAngle");
    }

    @Override
    public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
        nbt = super.writeToNBT(nbt);
        nbt.setIntArray("Processes", this.processes);
        nbt.setIntArray("CompostAmounts", this.compostAmounts);
        nbt.setIntArray("CompostTimes", this.compostTimes);
        nbt.setInteger("TotalCompostAmount", this.totalCompostAmount);
        nbt.setInteger("CompostedAmount", this.compostedAmount);
        nbt.setBoolean("Open", this.open);
        nbt.setFloat("LidAngle", this.lidAngle);
        return nbt;
    }

    @Override
    public SPacketUpdateTileEntity getUpdatePacket() {
        return new SPacketUpdateTileEntity(pos, 0, getUpdateTag());
    }

    @Override
    public void onDataPacket(NetworkManager net, SPacketUpdateTileEntity packet) {
        this.readFromNBT(packet.getNbtCompound());
    }

    @Override
    public NBTTagCompound getUpdateTag() {
        return writeToNBT(new NBTTagCompound());
    }

    /**
     * Returns the lid angle
     *
     * @param partialTicks
     * @return
     */
    public float getLidAngle(float partialTicks) {
        return this.open ? Math.min(this.lidAngle + OPEN_SPEED * partialTicks, MAX_OPEN) : Math.max(this.lidAngle - CLOSE_SPEED * partialTicks, MIN_OPEN);
    }

    /**
     * Returns the total compost at the end of the process
     *
     * @return
     */
    public int getTotalCompostAmount() {
        return this.totalCompostAmount;
    }

    /**
     * Returns the current total amount of compost
     *
     * @return
     */
    public int getCompostedAmount() {
        return this.compostedAmount;
    }

    @Override
    public int[] getSlotsForFace(EnumFacing side) {
        if (side == EnumFacing.UP) {
            int[] slots = new int[MAX_ITEMS];
            for (int i = 0; i < MAX_ITEMS; i++)
                slots[i] = i;
            return slots;
        } else if (side == EnumFacing.DOWN) {
            return new int[]{this.inventory.size() + 1};
        }
        return new int[0];
    }

    @Override
    public boolean canInsertItem(int index, @Nonnull ItemStack itemStackIn, EnumFacing direction) {
        ICompostBinRecipe recipe = CompostRecipe.getCompostRecipe(itemStackIn);
        return recipe != null && this.open && !itemStackIn.isEmpty() && direction == EnumFacing.UP && canAddItemToBin(recipe.getCompostAmount(itemStackIn), index);
    }

    @Override
    public boolean canExtractItem(int index, ItemStack stack, EnumFacing direction) {
        return this.open && EnumItemMisc.COMPOST.isItemOf(stack) && direction == EnumFacing.DOWN;
    }

    @Override
    public int getSizeInventory() {
        return this.inventory.size();
    }

    @Override
    public boolean isEmpty() {
        for(ItemStack stack : this.inventory) {
        	if(!stack.isEmpty()) {
        		return false;
        	}
        }
        return true;
    }

    @MethodsReturnNonnullByDefault
    @Override
    public ItemStack getStackInSlot(int index) {
        if (index >= 0 && index < getSizeInventory()) {
            return super.getStackInSlot(index);
        }
        return ItemStack.EMPTY;
    }

    @MethodsReturnNonnullByDefault
    @Override
    public ItemStack decrStackSize(int index, int count) {
        if (index < inventory.size() && !this.getStackInSlot(index).isEmpty()) {
            ItemStack itemstack;
            if (this.getStackInSlot(index).getCount() <= count) {
                this.processes[index] = 0;
                this.compostTimes[index] = 0;
                this.totalCompostAmount -= this.compostAmounts[index];
                this.compostAmounts[index] = 0;
                return super.decrStackSize(index, count);
            } else {
                itemstack = this.getStackInSlot(index).splitStack(count);
                if (this.getStackInSlot(index).getCount() == 0) {
                    this.setInventorySlotContents(index, ItemStack.EMPTY);
                }
                this.markDirty();
                return itemstack;
            }
        }

        return ItemStack.EMPTY;
    }

    @MethodsReturnNonnullByDefault
    @Override
    public ItemStack removeStackFromSlot(int index) {
        if (!this.inventory.get(index).isEmpty()) {
            this.processes[index] = 0;
            this.compostTimes[index] = 0;
            this.totalCompostAmount -= this.compostAmounts[index];
            this.compostAmounts[index] = 0;
            return super.removeStackFromSlot(index);
        } else {
            return ItemStack.EMPTY;
        }
    }

    @Override
    public void setInventorySlotContents(int index, @Nullable ItemStack stack) {
        if (index < MAX_ITEMS) {
            ICompostBinRecipe recipe = CompostRecipe.getCompostRecipe(stack);
            if (recipe != null) {
                this.addItemToBin(stack, recipe.getCompostAmount(stack), recipe.getCompostingTime(stack), false);
            }
        }
    }

    @Override
    public int getInventoryStackLimit() {
        return 1;
    }

    @Override
    public boolean isUsableByPlayer(EntityPlayer player) {
        return false;
    }

    @Override
    public boolean isItemValidForSlot(int index, ItemStack stack) {
        ICompostBinRecipe recipe = CompostRecipe.getCompostRecipe(stack);
        return recipe != null && canAddItemToBin(recipe.getCompostAmount(stack), index);
    }

}

package thebetweenlands.common.world.storage;

import java.io.File;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

import javax.annotation.Nullable;

import com.google.common.base.Predicate;

import gnu.trove.iterator.TObjectLongIterator;
import gnu.trove.map.TObjectLongMap;
import gnu.trove.map.hash.TObjectLongHashMap;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.ITickable;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.ChunkPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.World;
import net.minecraft.world.chunk.Chunk;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.network.IGenericDataManagerAccess;
import thebetweenlands.api.storage.IChunkStorage;
import thebetweenlands.api.storage.IDeferredStorageOperation;
import thebetweenlands.api.storage.ILocalStorage;
import thebetweenlands.api.storage.ILocalStorageHandle;
import thebetweenlands.api.storage.ILocalStorageHandler;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.LocalStorageReference;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.network.clientbound.MessageSyncLocalStorageData;
import thebetweenlands.common.registries.StorageRegistry;

public class LocalStorageHandlerImpl implements ILocalStorageHandler {
	private final IWorldStorage worldStorage;
	private final World world;
	private final File localStorageDir;

	private final Map<StorageID, ILocalStorage> localStorage = new HashMap<>();
	private final List<ILocalStorage> tickableLocalStorage = new ArrayList<>();
	private final List<ILocalStorage> pendingUnreferencedStorages = new ArrayList<>();

	private final TObjectLongMap<LocalRegionData> pendingUnreferencedRegions = new TObjectLongHashMap<>();

	private final LocalRegionCache regionCache;

	private final LocalStorageSaveHandler saveHandler = new LocalStorageSaveHandler();

	public LocalStorageHandlerImpl(IWorldStorage worldStorage) {
		this.worldStorage = worldStorage;
		this.world = worldStorage.getWorld();
		String dimFolder = this.world.provider.getSaveFolder();
		this.localStorageDir = new File(this.world.getSaveHandler().getWorldDirectory(), (dimFolder != null && dimFolder.length() > 0 ? dimFolder + File.separator : "") + "data" + File.separator + "local_storage" + File.separator);
		this.regionCache = new LocalRegionCache(this, new File(this.localStorageDir, "region"));
	}

	@Override
	public IWorldStorage getWorldStorage() {
		return this.worldStorage;
	}

	@Override
	public boolean addLocalStorage(ILocalStorage storage) {
		return this.addLocalStorageInternal(storage, true);
	}

	protected boolean addLocalStorageInternal(ILocalStorage storage, boolean isInitialAdd) {
		if(!this.localStorage.containsKey(storage.getID())) {
			this.localStorage.put(storage.getID(), storage);

			if(storage instanceof ITickable) {
				this.tickableLocalStorage.add(storage);
			}

			if(isInitialAdd) {
				storage.onAdded();
			}

			storage.onLoaded();

			boolean isReferenced = false;

			//Add already loaded references
			for(ChunkPos referenceChunk : storage.getLinkedChunks()) {
				Chunk chunk = this.world.getChunkProvider().getLoadedChunk(referenceChunk.x, referenceChunk.z);
				if(chunk != null) {
					IChunkStorage chunkStorage = this.worldStorage.getChunkStorage(chunk);
					if(chunkStorage != null) {
						LocalStorageReference reference = chunkStorage.getReference(storage.getID());
						if(reference != null) {
							isReferenced = true;

							if(!storage.getLoadedReferences().contains(reference)) {
								//Add reference
								storage.loadReference(reference);
							}
						}
					}
				}
			}

			if(!isReferenced && isInitialAdd && !this.world.isRemote) {
				//Queue storage to be checked in the next tick.
				//If it is still unreferenced it will be unloaded.
				this.pendingUnreferencedStorages.add(storage);
			}

			return true;
		}
		return false;
	}

	@Override
	public boolean removeLocalStorage(ILocalStorage storage) {
		if(this.localStorage.containsKey(storage.getID())) {
			storage.onRemoving();

			if(!this.world.isRemote) {
				storage.unlinkAllChunks();
			}

			this.localStorage.remove(storage.getID());

			Iterator<ILocalStorage> tickableIt = this.tickableLocalStorage.iterator();
			while(tickableIt.hasNext()) {
				ILocalStorage tickableStorage = tickableIt.next();
				if(storage.getID().equals(tickableStorage.getID())) {
					tickableIt.remove();
				}
			}

			Iterator<ILocalStorage> pendingIt = this.pendingUnreferencedStorages.iterator();
			while(pendingIt.hasNext()) {
				ILocalStorage pendingStorage = pendingIt.next();
				if(storage.getID().equals(pendingStorage.getID())) {
					pendingIt.remove();
				}
			}

			boolean wasSavedToRegion = false;

			if(!this.world.isRemote) {
				wasSavedToRegion = this.deleteLocalStorageFileInternal(storage);
			}

			storage.onUnloaded();

			storage.onRemoved();

			//A region only has a reference from a storage if that storage was new and saved to that
			//region or if it was loaded from that region. Only in those cases the region reference
			//counter needs to be decremented and the region unloaded if no longer referenced.
			if(wasSavedToRegion && !this.world.isRemote) {
				LocalRegion region = storage.getRegion();

				if(region != null) {
					this.decrRegionRef(this.regionCache.getCachedRegion(region), null, true);
				}
			}

			return true;
		}
		return false;
	}

	@Override
	public ILocalStorage getLocalStorage(StorageID id) {
		return this.localStorage.get(id);
	}

	@SuppressWarnings("unchecked")
	@Override
	public <T extends ILocalStorage> List<T> getLocalStorages(Class<T> type, double x, double z, @Nullable Predicate<T> filter) {
		List<T> storages = new ArrayList<>();
		int cx = MathHelper.floor(x) >> 4;
		int cz = MathHelper.floor(z) >> 4;
		Chunk chunk = this.world.getChunk(cx, cz);
		IChunkStorage chunkStorage = this.getWorldStorage().getChunkStorage(chunk);
		if(chunkStorage != null) {
			for(LocalStorageReference ref : chunkStorage.getLocalStorageReferences()) {
				ILocalStorage localStorage = this.getLocalStorage(ref.getID());
				if(localStorage != null && localStorage.getBoundingBox() != null && type.isAssignableFrom(localStorage.getClass())
						&& (filter == null || filter.apply((T) localStorage))) {
					if(!storages.contains(localStorage)) {
						storages.add((T) localStorage);
					}
				}
			}
		}
		return storages;
	}

	@SuppressWarnings("unchecked")
	@Override
	public <T extends ILocalStorage> List<T> getLocalStorages(Class<T> type, AxisAlignedBB aabb, @Nullable Predicate<T> filter) {
		List<T> storages = new ArrayList<>();
		int sx = MathHelper.floor(aabb.minX) >> 4;
		int sz = MathHelper.floor(aabb.minZ) >> 4;
		int ex = MathHelper.floor(aabb.maxX) >> 4;
		int ez = MathHelper.floor(aabb.maxZ) >> 4;
		for(int cx = sx; cx <= ex; cx++) {
			for(int cz = sz; cz <= ez; cz++) {
				Chunk chunk = this.world.getChunk(cx, cz);
				IChunkStorage chunkStorage = this.getWorldStorage().getChunkStorage(chunk);
				if(chunkStorage != null) {
					for(LocalStorageReference ref : chunkStorage.getLocalStorageReferences()) {
						ILocalStorage localStorage = this.getLocalStorage(ref.getID());
						if(localStorage != null && localStorage.getBoundingBox() != null && type.isAssignableFrom(localStorage.getClass()) && localStorage.getBoundingBox().intersects(aabb)
								&& (filter == null || filter.apply((T) localStorage))) {
							if(!storages.contains(localStorage)) {
								storages.add((T) localStorage);
							}
						}
					}
				}
			}
		}
		return storages;
	}

	@Override
	public void deleteLocalStorageFile(ILocalStorage storage) {
		this.deleteLocalStorageFileInternal(storage);
	}

	private boolean deleteLocalStorageFileInternal(ILocalStorage storage) {
		if(storage.getRegion() == null) {
			File file = new File(this.getLocalStorageDirectory(), storage.getID().getStringID() + ".dat");
			this.saveHandler.queueLocalStorage(file, null);
		} else {
			LocalRegionData data = this.regionCache.getOrCreateRegion(storage.getRegion(), false);

			if(data != null) {
				this.incrRegionRef(data);

				try {
					return data.deleteLocalStorage(this.regionCache.getDir(), storage.getID());
				} finally {
					this.decrRegionRef(data, null, true);
				}
			}
		}

		return false;
	}

	@Override
	public void saveLocalStorageFile(ILocalStorage storage) {
		this.saveLocalStorageFile(storage, false);
	}

	private void saveLocalStorageFile(ILocalStorage storage, boolean skipRegionUnloading) {
		NBTTagCompound nbt = this.saveLocalStorageToNBT(new NBTTagCompound(), storage);
		if(storage.getRegion() == null) {
			File file = new File(this.getLocalStorageDirectory(), storage.getID().getStringID() + ".dat");
			this.saveHandler.queueLocalStorage(file, nbt);
		} else {
			LocalRegion region = storage.getRegion();
			LocalRegionData data = this.regionCache.getOrCreateRegion(region);

			boolean isLoaded = !storage.getLoadedReferences().isEmpty() && this.getLocalStorage(storage.getID()) != null;
			boolean isFromRegion = data.getLocalStorageNBT(storage.getID()) != null;
			boolean isNewStorage = isLoaded && !isFromRegion;

			this.incrRegionRef(data);

			try {
				data.setLocalStorageNBT(storage.getID(), nbt);
			} finally {
				if(skipRegionUnloading) {
					this.decrRegionRef(data, null, false);
				} else {
					//If the region is new, i.e. was properly added but not loaded from a region, then
					//the region need not be unloaded or the region reference counter need not be decreased,
					//because we can be sure that this will happen later on.
					//In all other cases this should normally not cause the region to be unloaded unless the local storage
					//is a dangling instance or the region was not loaded properly, because when loaded properly the region
					//should also be loaded and be referenced accordingly. The only safe way to proceed if the region was
					//not loaded or not referenced properly is to immediately unload the region again to prevent a dangling region.
					if(!isNewStorage && this.decrRegionRef(data, null, true)) {
						TheBetweenlands.logger.warn(String.format("Saving local storage with ID %s, but its region %s was not loaded. This should not happen...", storage.getID().getStringID(), data.getID()));
					}
				}
			}
		}
	}

	@Nullable
	private ILocalStorage loadLocalStorageUnsafe(LocalStorageReference reference) {
		if(!this.world.isRemote) {
			try {
				ILocalStorage storage = this.createLocalStorageFromFile(reference);
				if(storage != null) {
					this.addLocalStorageInternal(storage, false);

					LocalRegion region = storage.getRegion();
					if(region != null) {
						LocalRegionData data = this.regionCache.getOrCreateRegion(region);
						this.incrRegionRef(data);
					}
				}
				return storage;
			} catch(Exception ex) {
				TheBetweenlands.logger.error(String.format("Failed loading local storage with ID %s at %s", reference.getID().getStringID(), "[x=" + reference.getChunk().x + ", z=" + reference.getChunk().z + "]"), ex);
			}
		}
		return null;
	}

	@Deprecated
	@Override
	public ILocalStorage loadLocalStorage(LocalStorageReference reference) {
		return this.loadLocalStorageUnsafe(reference);
	}

	@Override
	public ILocalStorageHandle getOrLoadLocalStorage(LocalStorageReference reference) {
		ILocalStorage storage = this.getLocalStorage(reference.getID());

		//If not already loaded try to load from file
		if(storage == null && !this.world.isRemote) {
			storage = this.loadLocalStorageUnsafe(reference);
		}

		if(storage != null) {
			return new LocalStorageHandleImpl(storage, reference);
		}

		return null;
	}

	/**
	 * Creates an instance of the local storage specified by the reference
	 * @param reference
	 * @return
	 */
	@Nullable
	private ILocalStorage createLocalStorageFromFile(LocalStorageReference reference) {
		if(!reference.hasRegion()) {
			File file = new File(this.getLocalStorageDirectory(), reference.getID().getStringID() + ".dat");
			try {
				NBTTagCompound nbt = this.saveHandler.loadFileNbt(file);;
				if(nbt != null) {
					return this.createLocalStorageFromNBT(nbt, null);
				}
			} catch(Exception ex) {
				TheBetweenlands.logger.error(String.format("Failed reading local storage %s from file: %s", reference.getID().getStringID(), file.getAbsolutePath()), ex);
			}
		} else {
			LocalRegionData region = this.regionCache.getOrCreateRegion(reference.getRegion());
			NBTTagCompound nbt = region.getLocalStorageNBT(reference.getID());
			if(nbt != null) {
				return this.createLocalStorageFromNBT(nbt, reference.getRegion());
			}
		}
		return null;
	}

	private void incrRegionRef(@Nullable LocalRegionData data) {
		if(data != null) {
			data.incrRefCounter();

			if(data.hasReferences()) {
				this.pendingUnreferencedRegions.remove(data);
			}
		}
	}

	private boolean decrRegionRef(@Nullable LocalRegionData data, @Nullable StorageID checkID, boolean saveAndUnload) {
		if(data != null && (checkID == null || data.getLocalStorageNBT(checkID) != null)) {
			data.decrRefCounter();

			if(!data.hasReferences()) {
				if(saveAndUnload) {
					this.pendingUnreferencedRegions.put(data, this.world.getTotalWorldTime());
				}

				return true;
			}
		}

		return false;
	}

	@Override
	public boolean unloadLocalStorage(ILocalStorage storage) {
		if(this.localStorage.containsKey(storage.getID())) {
			//Only save if dirty
			if(!this.world.isRemote && storage.isDirty()) {
				//Skip region unloading because that'll be handled after
				//unloading the local storage
				this.saveLocalStorageFile(storage, true);
				storage.setDirty(false);
			}

			this.localStorage.remove(storage.getID());

			Iterator<ILocalStorage> tickableIt = this.tickableLocalStorage.iterator();
			while(tickableIt.hasNext()) {
				ILocalStorage tickableStorage = tickableIt.next();
				if(storage.getID().equals(tickableStorage.getID())) {
					tickableIt.remove();
				}
			}

			Iterator<ILocalStorage> pendingIt = this.pendingUnreferencedStorages.iterator();
			while(pendingIt.hasNext()) {
				ILocalStorage pendingStorage = pendingIt.next();
				if(storage.getID().equals(pendingStorage.getID())) {
					pendingIt.remove();
				}
			}

			storage.onUnloaded();

			if(!this.world.isRemote) {
				LocalRegion region = storage.getRegion();

				if(region != null) {
					//A region only has a reference from a storage if that storage was new and saved to that
					//region or if it was loaded from that region. Only in those cases the region reference
					//counter needs to be decremented and the region unloaded if no longer referenced, hence
					//decrRegionRef needs to check if the region data contains that storage.
					this.decrRegionRef(this.regionCache.getCachedRegion(region), storage.getID(), true);
				}
			}

			return true;
		}
		return false;
	}

	@Override
	public Collection<ILocalStorage> getLoadedStorages() {
		return Collections.unmodifiableCollection(this.localStorage.values());
	}

	@Override
	public File getLocalStorageDirectory() {
		return this.localStorageDir;
	}

	@Override
	public void update() {
		for(int i = 0; i < this.tickableLocalStorage.size(); i++) {
			ILocalStorage localStorage = this.tickableLocalStorage.get(i);
			((ITickable)localStorage).update();

			IGenericDataManagerAccess dataManager = localStorage.getDataManager();
			if(dataManager != null) {
				dataManager.update();
				if(dataManager.isDirty()) {
					MessageSyncLocalStorageData message = new MessageSyncLocalStorageData(localStorage, false);
					for (EntityPlayerMP watcher : localStorage.getWatchers()) {
						TheBetweenlands.networkWrapper.sendTo(message, watcher);
					}
				}
			}
		}

		if(!this.world.isRemote) {
			for(int i = 0; i < this.pendingUnreferencedStorages.size(); i++) {
				ILocalStorage localStorage = this.pendingUnreferencedStorages.get(i);

				if(localStorage.getLoadedReferences().isEmpty() && this.getLocalStorage(localStorage.getID()) != null) {
					//Storage is not referenced by any chunk and being added for the first time.
					//Linking probably deferred. Save and unload storage until needed.
					this.unloadLocalStorage(localStorage);
				}
			}

			TObjectLongIterator<LocalRegionData> pendingUnreferencedRegionsIT = this.pendingUnreferencedRegions.iterator();
			while(pendingUnreferencedRegionsIT.hasNext()) {
				pendingUnreferencedRegionsIT.advance();

				if(this.world.getTotalWorldTime() - pendingUnreferencedRegionsIT.value() > 20) {
					LocalRegionData data = pendingUnreferencedRegionsIT.key();

					pendingUnreferencedRegionsIT.remove();

					if(data.isDirty()) {
						data.saveRegion(this.regionCache.getDir());
					}

					this.regionCache.removeRegion(data.getRegion());
				}
			}
		}
		this.pendingUnreferencedStorages.clear();
	}

	@Override
	public ILocalStorage createLocalStorageFromNBT(NBTTagCompound nbt, @Nullable LocalRegion region) {
		ResourceLocation type = new ResourceLocation(nbt.getString("type"));
		StorageID id = StorageID.readFromNBT(nbt);
		ILocalStorage storage = this.createLocalStorage(type, id, region);
		storage.readFromNBT(nbt.getCompoundTag("data"));
		return storage;
	}

	@Override
	public ILocalStorage createLocalStorage(ResourceLocation type, StorageID id, @Nullable LocalRegion region) {
		StorageRegistry.Factory<? extends ILocalStorage> factory = StorageRegistry.getStorageFactory(type);
		if (factory == null) {
			throw new RuntimeException("Local storage type not mapped: " + type);
		}
		return factory.create(this.worldStorage, id, region);
	}

	@Override
	public NBTTagCompound saveLocalStorageToNBT(NBTTagCompound nbt, ILocalStorage storage) {
		ResourceLocation type = StorageRegistry.getStorageId(storage.getClass());
		if (type == null) {
			throw new RuntimeException("Local storage type not mapped: " + storage);
		}
		nbt.setString("type", type.toString());
		storage.getID().writeToNBT(nbt);
		nbt.setTag("data", storage.writeToNBT(new NBTTagCompound()));
		return nbt;
	}

	@Override
	public void queueDeferredOperation(ChunkPos chunk, IDeferredStorageOperation operation) {
		//Run immediately if chunk is already loaded
		Chunk loadedChunk = this.getWorldStorage().getWorld().getChunkProvider().getLoadedChunk(chunk.x, chunk.z);
		if(loadedChunk != null) {
			IChunkStorage chunkStorage = this.getWorldStorage().getChunkStorage(loadedChunk);
			operation.apply(chunkStorage);
			return;
		}

		LocalRegion region = LocalRegion.getFromBlockPos(chunk.x * 16, chunk.z * 16);
		LocalRegionData data = this.regionCache.getOrCreateRegion(region);

		this.incrRegionRef(data);

		try {
			NBTTagCompound chunkNbt = data.getChunkNBT(chunk);
			if(chunkNbt == null) {
				chunkNbt = new NBTTagCompound();
			}

			NBTTagList operationsNbt = chunkNbt.getTagList("DeferredOperations", Constants.NBT.TAG_COMPOUND);

			ResourceLocation type = StorageRegistry.getDeferredOperationId(operation.getClass());
			if (type == null) {
				throw new RuntimeException("Deferred storage operation type not mapped: " + operation);
			}

			NBTTagCompound nbt = new NBTTagCompound();
			nbt.setString("type", type.toString());
			nbt.setTag("data", operation.writeToNBT(new NBTTagCompound()));

			operationsNbt.appendTag(nbt);
			chunkNbt.setTag("DeferredOperations", operationsNbt);

			data.setChunkNBT(chunk, chunkNbt);
		} finally {
			this.decrRegionRef(data, null, true);
		}
	}

	@Override
	public void loadDeferredOperations(IChunkStorage storage) {
		ChunkPos chunk = storage.getChunk().getPos();

		LocalRegion region = LocalRegion.getFromBlockPos(chunk.x * 16, chunk.z * 16);
		LocalRegionData data = this.regionCache.getOrCreateRegion(region, false);

		if(data != null) {
			this.incrRegionRef(data);

			try {
				NBTTagCompound chunkNbt = data.getChunkNBT(chunk);

				if(chunkNbt != null && chunkNbt.hasKey("DeferredOperations", Constants.NBT.TAG_LIST)) {
					NBTTagList operationsNbt = chunkNbt.getTagList("DeferredOperations", Constants.NBT.TAG_COMPOUND);

					for(int i = 0; i < operationsNbt.tagCount(); i++) {
						NBTTagCompound nbt = operationsNbt.getCompoundTagAt(i);

						ResourceLocation type = new ResourceLocation(nbt.getString("type"));

						Supplier<? extends IDeferredStorageOperation> factory = StorageRegistry.getDeferredOperationFactory(type);
						if (factory == null) {
							TheBetweenlands.logger.error("Deferred storage operation type not mapped: " + type + ". Skipping...");
							continue;
						}

						IDeferredStorageOperation operation = factory.get();

						operation.readFromNBT(nbt.getCompoundTag("data"));

						operation.apply(storage);
					}

					//Clear deferred operations
					chunkNbt.removeTag("DeferredOperations");

					data.setChunkNBT(chunk, chunkNbt);
				}
			} finally {
				this.decrRegionRef(data, null, true);
			}
		}
	}

	public LocalStorageSaveHandler getSaveHandler() {
		return this.saveHandler;
	}

	@Override
	public void saveAll() {
		//Save loaded storages
		for(ILocalStorage localStorage : this.getLoadedStorages()) {
			//Only save if dirty
			if(localStorage.isDirty()) {
				this.saveLocalStorageFile(localStorage);
				localStorage.setDirty(false);
			}
		}

		//Save and unload all unreferenced regions
		for(LocalRegionData data : this.pendingUnreferencedRegions.keySet()) {
			if(data.isDirty()) {
				data.saveRegion(this.regionCache.getDir());
			}

			this.regionCache.removeRegion(data.getRegion());
		}
		this.pendingUnreferencedRegions.clear();

		//Save rest of regional cache
		this.regionCache.saveAllRegions();
	}
}

package thebetweenlands.common.world.storage;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;

import javax.annotation.Nullable;

import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.ChunkPos;
import net.minecraft.world.chunk.Chunk;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.capabilities.Capability;
import net.minecraftforge.common.capabilities.CapabilityDispatcher;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.fml.common.network.simpleimpl.IMessage;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
import thebetweenlands.api.event.AttachLocalStorageCapabilitiesEvent;
import thebetweenlands.api.storage.IChunkStorage;
import thebetweenlands.api.storage.ILocalStorage;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.LocalStorageReference;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.network.clientbound.MessageAddLocalStorage;
import thebetweenlands.common.network.clientbound.MessageRemoveLocalStorage;
import thebetweenlands.common.world.storage.operation.DeferredLinkOperation;

public abstract class LocalStorageImpl implements ILocalStorage {
	private final IWorldStorage worldStorage;
	private final LocalRegion region;
	private final StorageID id;

	private CapabilityDispatcher capabilities;
	private boolean dirty;

	private final List<ChunkPos> linkedChunks = new ArrayList<>();
	private final List<LocalStorageReference> loadedReferences = new ArrayList<>();

	//protected boolean requiresSync = false;

	private final List<EntityPlayerMP> watchers = new ArrayList<>();
	private final List<EntityPlayerMP> duplicateWatchers = new ArrayList<>();

	private boolean loaded = false;

	public LocalStorageImpl(IWorldStorage worldStorage, StorageID id, @Nullable LocalRegion region) {
		this.worldStorage = worldStorage;
		this.id = id;
		this.region = region;

		//Gather capabilities
		AttachLocalStorageCapabilitiesEvent event = new AttachLocalStorageCapabilitiesEvent(this);
		MinecraftForge.EVENT_BUS.post(event);
		this.capabilities = event.getCapabilities().size() > 0 ? new CapabilityDispatcher(event.getCapabilities(), null) : null;
	}

	@Override
	public boolean hasCapability(Capability<?> capability, EnumFacing facing) {
		return this.capabilities == null ? false : this.capabilities.hasCapability(capability, facing);
	}

	@Override
	public <T> T getCapability(Capability<T> capability, EnumFacing facing) {
		return this.capabilities == null ? null : this.capabilities.getCapability(capability, facing);
	}

	@Override
	public IWorldStorage getWorldStorage() {
		return this.worldStorage;
	}

	@Override
	public StorageID getID() {
		return this.id;
	}

	@Override
	public LocalRegion getRegion() {
		return this.region;
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		if(this.capabilities != null && nbt.hasKey("ForgeCaps")) {
			this.capabilities.deserializeNBT(nbt.getCompoundTag("ForgeCaps"));
		}

		this.readReferenceChunks(nbt);
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		if(this.capabilities != null) {
			NBTTagCompound caps = this.capabilities.serializeNBT();
			if(caps.getSize() > 0) {
				nbt.setTag("ForgeCaps", caps);
			}
		}

		this.writeReferenceChunks(nbt);

		return nbt;
	}

	@Override
	public void readInitialPacket(NBTTagCompound nbt) {
		this.readReferenceChunks(nbt);
	}

	@Override
	public NBTTagCompound writeInitialPacket(NBTTagCompound nbt) {
		this.writeReferenceChunks(nbt);
		return nbt;
	}

	protected final void writeReferenceChunks(NBTTagCompound nbt) {
		NBTTagList referenceChunkList = new NBTTagList();
		for(ChunkPos referenceChunk : this.linkedChunks) {
			NBTTagCompound referenceChunkNbt = new NBTTagCompound();
			referenceChunkNbt.setInteger("x", referenceChunk.x);
			referenceChunkNbt.setInteger("z", referenceChunk.z);
			referenceChunkList.appendTag(referenceChunkNbt);
		}
		nbt.setTag("ReferenceChunks", referenceChunkList);
	}

	protected final void readReferenceChunks(NBTTagCompound nbt) {
		this.linkedChunks.clear();
		NBTTagList referenceChunkList = nbt.getTagList("ReferenceChunks", Constants.NBT.TAG_COMPOUND);
		for(int i = 0; i < referenceChunkList.tagCount(); i++) {
			NBTTagCompound referenceChunkNbt = referenceChunkList.getCompoundTagAt(i);
			this.linkedChunks.add(new ChunkPos(referenceChunkNbt.getInteger("x"), referenceChunkNbt.getInteger("z")));
		}
	}

	@Override
	public void markDirty() {
		this.setDirty(true);
	}

	/**
	 * Sets whether the data is dirty and needs to be saved to the file
	 * @param dirty
	 * @return
	 */
	@Override
	public void setDirty(boolean dirty) {
		this.dirty = dirty;
	}

	@Override
	public boolean isDirty() {
		return this.dirty;
	}

	@Override
	public List<ChunkPos> getLinkedChunks() {
		return Collections.unmodifiableList(this.linkedChunks);
	}

	@Override
	@SideOnly(Side.CLIENT)
	public void setLinkedChunks(List<ChunkPos> linkedChunks) {
		this.linkedChunks.clear();
		this.linkedChunks.addAll(linkedChunks);
	}

	@Override
	public void onLoaded() {
		this.loaded = true;
	}

	@Override
	public void onUnloaded() {
		this.loaded = false;
	}

	@Override
	public void onRemoved() {

	}

	@Override
	public void onRemoving() {
		//Notify clients when shared storage is removed.
		//This is done before onRemoved so that the list of watchers is not yet empty.
		if(!this.getWorldStorage().getWorld().isRemote) {
			if (!this.getWatchers().isEmpty()) {
				this.sendMessageToAllWatchers(new MessageRemoveLocalStorage(this.getID()));
			}
		}
	}

	@Override
	public Collection<LocalStorageReference> getLoadedReferences() {
		return Collections.unmodifiableCollection(this.loadedReferences);
	}

	@Override
	public boolean loadReference(LocalStorageReference reference) {
		if(!this.loadedReferences.contains(reference)) {
			return this.loadedReferences.add(reference);
		}
		return false;
	}

	@Override
	public boolean unloadReference(LocalStorageReference reference) {
		return this.loadedReferences.remove(reference);
	}

	@Override
	public boolean addWatcher(IChunkStorage chunkStorage, EntityPlayerMP player) {
		boolean contained = this.duplicateWatchers.contains(player);
		this.duplicateWatchers.add(player);
		if(!contained) {
			this.watchers.add(player);
			this.onWatched(player);
		}
		return !contained;
	}

	/**
	 * Called when a new watcher is added
	 * @param player
	 */
	protected void onWatched(EntityPlayerMP player) {
		this.sendDataToPlayer(new MessageAddLocalStorage(this), player);
	}

	@Override
	public boolean removeWatcher(IChunkStorage chunkStorage, EntityPlayerMP player) {
		boolean contained = this.duplicateWatchers.remove(player);
		if(contained && !this.duplicateWatchers.contains(player)) {
			this.watchers.remove(player);
			this.onUnwatched(player);
		}
		return contained;
	}

	/**
	 * Called when a player stops watching this local storage
	 * @param player
	 */
	protected void onUnwatched(EntityPlayerMP player) {

	}

	@Override
	public Collection<EntityPlayerMP> getWatchers() {
		return Collections.unmodifiableCollection(this.watchers);
	}

	@Override
	public boolean unlinkAllChunks() {
		boolean changed = false;
		boolean allUnlinked = true;
		List<ChunkPos> chunks = new ArrayList<>(this.linkedChunks.size());
		chunks.addAll(this.linkedChunks);
		Iterator<ChunkPos> it = chunks.iterator();
		ChunkPos pos = null;
		while(it.hasNext()) {
			pos = it.next();
			Chunk chunk = this.worldStorage.getWorld().getChunk(pos.x, pos.z);
			IChunkStorage chunkData = this.worldStorage.getChunkStorage(chunk);
			if(chunkData == null || !chunkData.unlinkLocalStorage(this)) {
				allUnlinked = false;
			} else if(chunkData != null) {
				changed = true;
			}
		}
		if(changed) {
			this.setDirty(true);
		}
		this.linkedChunks.clear();
		return allUnlinked;
	}

	@Override
	public boolean linkChunk(Chunk chunk) {
		ChunkPos chunkPos = new ChunkPos(chunk.x, chunk.z);
		if(!this.linkedChunks.contains(chunkPos)) {
			IChunkStorage chunkData = this.worldStorage.getChunkStorage(chunk);
			if(chunkData != null && chunkData.linkLocalStorage(this)) {
				if(this.linkedChunks.add(chunkPos)) {
					//TODO Send packet
					this.setDirty(true);
					return true;
				}
			}
		}
		return false;
	}

	@Override
	public void linkChunkDeferred(ChunkPos chunk) {
		if(!this.linkedChunks.contains(chunk) && this.linkedChunks.add(chunk)) {
			this.setDirty(true);
			this.worldStorage.getLocalStorageHandler().queueDeferredOperation(chunk, new DeferredLinkOperation(new LocalStorageReference(chunk, this.getID(), this.getRegion())));
		}
	}

	@Override
	public boolean unlinkChunk(Chunk chunk) {
		ChunkPos chunkPos = new ChunkPos(chunk.x, chunk.z);
		if(this.linkedChunks.contains(chunkPos)) {
			IChunkStorage chunkData = this.worldStorage.getChunkStorage(chunk);
			if(chunkData != null) {
				chunkData.unlinkLocalStorage(this);
				if(this.linkedChunks.remove(chunkPos)) {
					//TODO Send packet
					this.setDirty(true);
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Sends the message to all watching players
	 */
	protected void sendMessageToAllWatchers(IMessage message) {
		for (EntityPlayerMP watcher : this.getWatchers()) {
			this.sendDataToPlayer(message, watcher);
		}
	}

	/**
	 * Sends the message to a player
	 * @param player
	 */
	protected void sendDataToPlayer(IMessage message, EntityPlayerMP player) {
		TheBetweenlands.networkWrapper.sendTo(message, player);
	}

	@Override
	public boolean isLoaded() {
		return this.loaded;
	}
}

package thebetweenlands.common.world.storage;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.Map.Entry;
import java.util.UUID;

import javax.annotation.Nullable;

import net.minecraft.nbt.CompressedStreamTools;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.world.World;
import net.minecraft.world.WorldServer;
import net.minecraftforge.event.world.WorldEvent;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import thebetweenlands.api.storage.IOfflinePlayerDataHandler;
import thebetweenlands.common.TheBetweenlands;

public class OfflinePlayerHandlerImpl implements IOfflinePlayerDataHandler {
	private static class OfflinePlayerData {
		private NBTTagCompound nbt;
		private boolean dirty;
		private long timestamp;

		protected void setData(NBTTagCompound nbt) {
			this.nbt = nbt;
			this.dirty = true;
			this.refreshUseTimestamp();
		}

		protected NBTTagCompound getData() {
			return this.nbt;
		}

		protected void refreshUseTimestamp() {
			this.timestamp = System.currentTimeMillis();
		}

		protected boolean isExpired() {
			return System.currentTimeMillis() - this.timestamp > 30000;
		}

		protected boolean isDirty() {
			return this.dirty;
		}

		protected void resetDirty() {
			this.dirty = false;
		}
	}

	private Map<UUID, OfflinePlayerData> offlinePlayerDataCache = new HashMap<>();

	private WorldServer world;

	public OfflinePlayerHandlerImpl(WorldServer world) {
		this.world = world;
	}

	@Override
	public void updateCache() {
		Iterator<Entry<UUID, OfflinePlayerData>> playerDataIT = this.offlinePlayerDataCache.entrySet().iterator();
		while(playerDataIT.hasNext()) {
			Entry<UUID, OfflinePlayerData> entry = playerDataIT.next();

			OfflinePlayerData data = entry.getValue();

			if(data.isExpired()) {
				if(data.isDirty()) {
					this.saveOfflinePlayerDataSafely(entry.getKey(), data.getData());
				}

				playerDataIT.remove();
			}
		}
	}

	@Nullable
	@Override
	public NBTTagCompound getOfflinePlayerData(UUID playerUuid) {
		OfflinePlayerData data = this.offlinePlayerDataCache.get(playerUuid);
		if(data != null) {
			data.refreshUseTimestamp();
			return data.nbt;
		}

		NBTTagCompound nbt = this.loadOfflinePlayerDataSafely(playerUuid);
		if(nbt != null) {
			data = new OfflinePlayerData();
			data.setData(nbt);
			this.offlinePlayerDataCache.put(playerUuid, data);
			return nbt;
		}

		return null;
	}

	private File getOfflinePlayerDataFolder(WorldServer world) {
		File file = new File(new File(world.getSaveHandler().getWorldDirectory(), "playerdata"), "offline_player_data");
		file.mkdirs();
		return file;
	}

	@Nullable
	private NBTTagCompound loadOfflinePlayerDataSafely(UUID playerUuid) {
		try {
			return this.loadOfflinePlayerData(playerUuid);
		} catch(IOException ex) {
			TheBetweenlands.logger.error(String.format("Failed loading offline player data for UUID %s", playerUuid.toString()), ex);
		}
		return null;
	}

	@Nullable
	private NBTTagCompound loadOfflinePlayerData(UUID playerUuid) throws IOException {
		String fileName = playerUuid.toString();

		File file = new File(this.getOfflinePlayerDataFolder((WorldServer) this.world), fileName + ".dat");

		if(file.exists()) {
			return CompressedStreamTools.readCompressed(new FileInputStream(file));
		}

		return null;
	}

	@Override
	public void setOfflinePlayerData(UUID playerUuid, NBTTagCompound nbt) {
		OfflinePlayerData data = this.offlinePlayerDataCache.get(playerUuid);
		if(data != null) {
			data.setData(nbt);
		} else {
			data = new OfflinePlayerData();
			data.setData(nbt);
			this.offlinePlayerDataCache.put(playerUuid, data);
		}
	}

	private boolean saveOfflinePlayerDataSafely(UUID playerUuid, NBTTagCompound nbt) {
		try {
			this.saveOfflinePlayerData(playerUuid, nbt);
			return true;
		} catch(IOException ex) {
			TheBetweenlands.logger.error(String.format("Failed saving offline player data for UUID %s", playerUuid.toString()), ex);
		}
		return false;
	}

	private void saveOfflinePlayerData(UUID playerUuid, NBTTagCompound nbt) throws IOException {
		String fileName = playerUuid.toString();

		File folder = this.getOfflinePlayerDataFolder((WorldServer) this.world);

		File tempFile = new File(folder, fileName + ".dat.tmp");
		File currentFile = new File(folder, fileName + ".dat");

		CompressedStreamTools.writeCompressed(nbt, new FileOutputStream(tempFile));

		if (currentFile.exists()) {
			currentFile.delete();
		}

		if(!tempFile.renameTo(currentFile)) {
			throw new IOException(String.format("Failed renaming %s to %s", tempFile, currentFile));
		}
	}

	@Override
	public void saveAllOfflinePlayerData() {
		for(Entry<UUID, OfflinePlayerData> entry : this.offlinePlayerDataCache.entrySet()) {
			if(entry.getValue().isDirty()) {
				this.saveOfflinePlayerDataSafely(entry.getKey(), entry.getValue().getData());
			}
		}
	}

	private static OfflinePlayerHandlerImpl handler = null;

	@Nullable
	public static IOfflinePlayerDataHandler getHandler() {
		return handler;
	}

	private static WorldServer getMainWorld(World world) {
		if(world instanceof WorldServer && world == ((WorldServer) world).getMinecraftServer().getEntityWorld()) {
			return (WorldServer) world;
		}
		return null;
	}

	@SubscribeEvent
	public static void onWorldLoad(WorldEvent.Load event) {
		WorldServer world = getMainWorld(event.getWorld());
		if(world != null) {
			if(handler != null) {
				handler.saveAllOfflinePlayerData();
			}
			handler = new OfflinePlayerHandlerImpl((WorldServer) world);
		}
	}

	@SubscribeEvent
	public static void onWorldUnload(WorldEvent.Unload event) {
		WorldServer world = getMainWorld(event.getWorld());
		if(world != null) {
			if(handler != null) {
				handler.saveAllOfflinePlayerData();
			}
			handler = null;
		}
	}

	@SubscribeEvent
	public static void onWorldSave(WorldEvent.Save event) {
		WorldServer world = getMainWorld(event.getWorld());
		if(world != null && handler != null) {
			handler.saveAllOfflinePlayerData();
		}
	}

	@SubscribeEvent
	public static void onServerTick(TickEvent.ServerTickEvent event) {
		if(handler != null) {
			handler.updateCache();
		}
	}
}

package thebetweenlands.common.world.storage.location;

import javax.annotation.Nullable;

import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.BlockPos.MutableBlockPos;
import net.minecraft.world.World;
import net.minecraftforge.common.util.Constants;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.config.BetweenlandsConfig;
import thebetweenlands.common.registries.BlockRegistry;

public class LocationPortal extends LocationStorage {
	private BlockPos portalPos;
	private BlockPos otherPortalPos;
	private int otherPortalDimension;
	private boolean targetDimensionSet;

	public LocationPortal(IWorldStorage worldStorage, StorageID id, @Nullable LocalRegion region) {
		super(worldStorage, id, region);
	}

	public LocationPortal(IWorldStorage worldStorage, StorageID id, @Nullable LocalRegion region, BlockPos pos) {
		super(worldStorage, id, region);
		this.portalPos = pos;
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		super.readFromNBT(nbt);
		this.portalPos = BlockPos.fromLong(nbt.getLong("PortalPos"));
		if(nbt.hasKey("OtherPortalPos", Constants.NBT.TAG_LONG)) {
			this.otherPortalPos = BlockPos.fromLong(nbt.getLong("OtherPortalPos"));
		} else {
			this.otherPortalPos = null;
		}
		if(nbt.hasKey("OtherPortalDimension", Constants.NBT.TAG_INT)) {
			this.otherPortalDimension = nbt.getInteger("OtherPortalDimension");
		} else {
			//Legacy code for old portals that didn't support other dimensions
			int currDim = this.getWorldStorage().getWorld().provider.getDimension();
			if(currDim == BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId) {
				this.otherPortalDimension = 0;
			} else {
				this.otherPortalDimension = BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId;
			}
		}
		this.targetDimensionSet = nbt.getBoolean("TargetDimSet");
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		nbt = super.writeToNBT(nbt);
		nbt.setLong("PortalPos", this.portalPos.toLong());
		if(this.otherPortalPos != null) {
			nbt.setLong("OtherPortalPos", this.otherPortalPos.toLong());
		}
		nbt.setInteger("OtherPortalDimension", this.otherPortalDimension);
		nbt.setBoolean("TargetDimSet", this.targetDimensionSet);
		return nbt;
	}

	/**
	 * Returns the position of this portal
	 * @return
	 */
	public BlockPos getPortalPosition() {
		return this.portalPos;
	}

	/**
	 * Returns the position of the portal on the other side
	 * @return
	 */
	@Nullable
	public BlockPos getOtherPortalPosition() {
		return this.otherPortalPos;
	}

	/**
	 * Returns the dimension the other portal is in
	 * @return
	 */
	public int getOtherPortalDimension() {
		return this.otherPortalDimension;
	}

	/**
	 * Sets the position of the portal on the other side
	 * @param pos
	 */
	public void setOtherPortalPosition(int dim, @Nullable BlockPos pos) {
		this.otherPortalPos = pos;
		this.otherPortalDimension = dim;
		this.setDirty(true);
	}

	/**
	 * Sets the target dimension of this portal. A new portal
	 * will be generated on the other side when first entering the portal.
	 * The target dimension will be set in {@link #getOtherPortalDimension()},
	 * the link of this portal will be overwritten
	 * @param dim The target dimension
	 */
	public void setTargetDimension(int dim) {
		this.otherPortalPos = null;
		this.otherPortalDimension = dim;
		this.targetDimensionSet = true;
		this.setDirty(true);
	}

	/**
	 * Returns whether a target dimension was set. See {@link #setTargetDimension(int)}
	 * @return
	 */
	public boolean hasTargetDimension() {
		return this.targetDimensionSet;
	}

	/**
	 * Checks whether the portal is still valid and if not, removes the location 
	 * @return True if the portal was invalid and removed
	 */
	public boolean validateAndRemove() {
		World world = this.getWorldStorage().getWorld();
		AxisAlignedBB bounds = this.getBoundingBox();
		for(MutableBlockPos checkPos : MutableBlockPos.getAllInBoxMutable(new BlockPos(bounds.minX, bounds.minY, bounds.minZ), new BlockPos(bounds.maxX, bounds.maxY, bounds.maxZ))) {
			if(world.getBlockState(checkPos).getBlock() == BlockRegistry.TREE_PORTAL) {
				return false;
			}
		}
		return this.getWorldStorage().getLocalStorageHandler().removeLocalStorage(this);
	}
}

package thebetweenlands.common.world.storage.location;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

import javax.annotation.Nullable;

import gnu.trove.map.TObjectIntMap;
import gnu.trove.map.hash.TObjectIntHashMap;
import net.minecraft.entity.Entity;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.network.datasync.DataParameter;
import net.minecraft.network.datasync.DataSerializers;
import net.minecraft.util.math.AxisAlignedBB;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.ChunkPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.util.math.Vec3d;
import net.minecraft.util.math.Vec3i;
import net.minecraft.util.text.translation.I18n;
import net.minecraft.world.World;
import net.minecraftforge.common.util.Constants;
import net.minecraftforge.event.world.BlockEvent.BreakEvent;
import thebetweenlands.api.network.IGenericDataManagerAccess;
import thebetweenlands.api.storage.IWorldStorage;
import thebetweenlands.api.storage.LocalRegion;
import thebetweenlands.api.storage.StorageID;
import thebetweenlands.common.TheBetweenlands;
import thebetweenlands.common.network.datamanager.GenericDataManager;
import thebetweenlands.common.world.storage.BetweenlandsWorldStorage;
import thebetweenlands.common.world.storage.LocalStorageImpl;
import thebetweenlands.common.world.storage.location.guard.ILocationGuard;

public class LocationStorage extends LocalStorageImpl {
	private List<AxisAlignedBB> boundingBoxes = new ArrayList<>();
	private AxisAlignedBB enclosingBoundingBox;
	private EnumLocationType type;
	private int layer;
	private LocationAmbience ambience = null;
	private boolean inheritAmbience = true;
	private long locationSeed = 0L;

	protected GenericDataManager dataManager;

	private TObjectIntMap<Entity> titleDisplayCooldowns = new TObjectIntHashMap<Entity>();

	// Increment when stuff needs to be fixed and implement fix in fixData
	private static final int VERSION = 1;

	protected static final DataParameter<String> NAME = GenericDataManager.createKey(LocationStorage.class, DataSerializers.STRING);
	protected static final DataParameter<Boolean> VISIBLE = GenericDataManager.createKey(LocationStorage.class, DataSerializers.BOOLEAN);

	public LocationStorage(IWorldStorage worldStorage, StorageID id, @Nullable LocalRegion region) {
		this(worldStorage, id, region, "", EnumLocationType.NONE);
	}

	/**
	 * Creates a new location
	 * @param worldStorage
	 * @param id
	 */
	public LocationStorage(IWorldStorage worldStorage, StorageID id, @Nullable LocalRegion region, String name, EnumLocationType type) {
		super(worldStorage, id, region);

		this.dataManager = new GenericDataManager(this);

		this.dataManager.register(NAME, name);
		this.dataManager.register(VISIBLE, false);

		if(type == null) {
			type = EnumLocationType.NONE;
		}

		this.type = type;
	}

	@Override
	public IGenericDataManagerAccess getDataManager() {
		return this.dataManager;
	}

	/**
	 * Adds the specified bounding boxes
	 * @param boundingBoxes
	 * @return
	 */
	public LocationStorage addBounds(AxisAlignedBB... boundingBoxes) {
		for(AxisAlignedBB boundingBox : boundingBoxes) {
			this.boundingBoxes.add(boundingBox);
			this.markDirty();
		}
		this.updateEnclosingBounds();
		return this;
	}

	/**
	 * Returns the bounding boxes of this location
	 * @return
	 */
	public List<AxisAlignedBB> getBounds() {
		return Collections.unmodifiableList(this.boundingBoxes);
	}

	/**
	 * Removes the specified bounding boxes
	 * @param boundingBoxes
	 */
	public void removeBounds(AxisAlignedBB... boundingBoxes) {
		for(AxisAlignedBB boundingBox : boundingBoxes) {
			this.boundingBoxes.remove(boundingBox);
			this.markDirty();
		}
		this.updateEnclosingBounds();
	}

	/**
	 * Updates the enclosing bounding box
	 */
	protected void updateEnclosingBounds() {
		if(this.boundingBoxes.isEmpty()) {
			this.enclosingBoundingBox = null;
		} else if(this.boundingBoxes.size() == 1) {
			this.enclosingBoundingBox = this.boundingBoxes.get(0);
		} else {
			AxisAlignedBB union = this.boundingBoxes.get(0);
			for(AxisAlignedBB box : this.boundingBoxes) {
				union = union.union(box);
			}
			this.enclosingBoundingBox = union;
		}
	}

	/**
	 * Returns a bounding box that encloses all bounds
	 * @return
	 */
	public AxisAlignedBB getEnclosingBounds() {
		return this.enclosingBoundingBox;
	}

	@Override
	public void onAdded() {
		if(!this.getWorldStorage().getWorld().isRemote) {
			this.linkChunks();
		}
	}

	/**
	 * Links all chunks of this location.
	 * Called when the location is initially added to the world.
	 * If the location bounds are changed this needs to be called again manually.
	 * @return
	 */
	public LocationStorage linkChunks() {
		for(AxisAlignedBB boundingBox : this.boundingBoxes) {
			int sx = MathHelper.floor(boundingBox.minX) >> 4;
			int sz = MathHelper.floor(boundingBox.minZ) >> 4;
			int ex = MathHelper.floor(boundingBox.maxX) >> 4;
			int ez = MathHelper.floor(boundingBox.maxZ) >> 4;
			for(int cx = sx; cx <= ex; cx++) {
				for(int cz = sz; cz <= ez; cz++) {
					this.linkChunkSafely(new ChunkPos(cx, cz));
				}
			}
		}
		return this;
	}

	/**
	 * Returns the location guard. Must be created before
	 * {@link #readFromNBT(NBTTagCompound)} is called
	 * @return
	 */
	@Nullable
	public ILocationGuard getGuard() {
		return null;
	}

	/**
	 * Sets the location seed
	 * @param seed
	 * @return
	 */
	public LocationStorage setSeed(long seed) {
		this.locationSeed = seed;
		this.markDirty();
		return this;
	}

	/**
	 * Returns the location seed
	 * @return
	 */
	public long getSeed() {
		return this.locationSeed;
	}

	/**
	 * Sets whether this location should inherit ambiences from lower layers
	 * @param inherit
	 * @return
	 */
	public LocationStorage setInheritAmbience(boolean inherit) {
		this.inheritAmbience = inherit;
		this.ambience = null;
		this.markDirty();
		return this;
	}

	/**
	 * Sets whether this location is visible
	 * @param visible
	 * @return
	 */
	public LocationStorage setVisible(boolean visible) {
		this.dataManager.set(VISIBLE, visible);
		this.markDirty();
		return this;
	}

	/**
	 * Sets the location layer
	 * @param layer
	 * @return
	 */
	public LocationStorage setLayer(int layer) {
		this.layer = layer;
		this.markDirty();
		return this;
	}

	/**
	 * Returns the location layer
	 * @return
	 */
	public int getLayer() {
		return this.layer;
	}

	/**
	 * Sets the location ambience
	 * @param ambience
	 * @return
	 */
	public LocationStorage setAmbience(@Nullable LocationAmbience ambience) {
		if(ambience != null) {
			this.inheritAmbience = false;
			this.ambience = ambience;
			ambience.setLocation(this);
		} else {
			this.ambience = null;
		}
		this.markDirty();
		return this;
	}

	/**
	 * Returns whether the location has an ambience
	 * @return
	 */
	public boolean hasAmbience() {
		return this.ambience != null;
	}

	/**
	 * Returns the localized name of this location
	 * @return
	 */
	public String getLocalizedName() {
		return I18n.translateToLocal("location." + this.dataManager.get(NAME) + ".name");
	}

	public boolean hasLocalizedName() {
		return I18n.canTranslate("location." + this.dataManager.get(NAME) + ".name");
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		int savedVersion = nbt.getInteger("version");
		if(savedVersion != VERSION) {
			this.fixData(nbt, savedVersion, VERSION);
			this.markDirty(); // save new version
		}

		super.readFromNBT(nbt);

		this.readSharedNbt(nbt);
	}

	protected void readSharedNbt(NBTTagCompound nbt) {
		this.dataManager.set(NAME, nbt.getString("name"));
		if(this.dataManager.get(NAME).startsWith("translate:")) {
			this.dataManager.set(NAME, this.dataManager.get(NAME).replaceFirst("translate:", ""));
			this.setDirty(true);
		}
		this.boundingBoxes.clear();
		NBTTagList boundingBoxes = nbt.getTagList("bounds", Constants.NBT.TAG_COMPOUND);
		for(int i = 0; i < boundingBoxes.tagCount(); i++) {
			NBTTagCompound boxNbt = boundingBoxes.getCompoundTagAt(i);
			this.boundingBoxes.add(this.readAabb(boxNbt));
		}
		this.updateEnclosingBounds();
		this.type = EnumLocationType.fromName(nbt.getString("type"));
		this.layer = nbt.getInteger("layer");
		if(nbt.hasKey("ambience")) {
			NBTTagCompound ambienceTag = nbt.getCompoundTag("ambience");
			this.ambience = LocationAmbience.readFromNBT(this, ambienceTag);
		}
		this.dataManager.set(VISIBLE, nbt.getBoolean("visible"));
		this.locationSeed = nbt.getLong("seed");
	}

	protected void fixData(NBTTagCompound nbt, int oldVersion, int newVersion) {
		if(oldVersion == 0) {
			// Visibility default was changed to false in update
			// v3.4.0 causing locations generated afterwards to no
			// longer be visible

			String name = nbt.getString("name");

			if(this.doesVisibilityNeedFixing(name)) {
				TheBetweenlands.logger.debug("Fixing visibility of location {}", name);
				nbt.setBoolean("visible", true);
			}
		}
	}

	private boolean doesVisibilityNeedFixing(String name) {
		switch(name) {
		case "ruins":
		case "small_dungeon":
		case "tar_pool_dungeon":
		case "cragrock_tower":
		case "wight_tower":
		case "wight_tower_puzzle":
		case "wight_tower_teleporter":
		case "wight_tower_boss":
		case "abandoned_shack":
		case "underground_ruins":
			return true;
		default:
			return false;
		}
	}

	protected NBTTagCompound writeAabb(AxisAlignedBB aabb) {
		NBTTagCompound boxNbt = new NBTTagCompound();
		boxNbt.setDouble("minX", aabb.minX);
		boxNbt.setDouble("minY", aabb.minY);
		boxNbt.setDouble("minZ", aabb.minZ);
		boxNbt.setDouble("maxX", aabb.maxX);
		boxNbt.setDouble("maxY", aabb.maxY);
		boxNbt.setDouble("maxZ", aabb.maxZ);
		return boxNbt;
	}

	protected AxisAlignedBB readAabb(NBTTagCompound nbt) {
		double minX = nbt.getDouble("minX");
		double minY = nbt.getDouble("minY");
		double minZ = nbt.getDouble("minZ");
		double maxX = nbt.getDouble("maxX");
		double maxY = nbt.getDouble("maxY");
		double maxZ = nbt.getDouble("maxZ");
		return new AxisAlignedBB(minX, minY, minZ, maxX, maxY, maxZ);
	}

	/**
	 * Reads the guard data from NBT
	 * @param nbt
	 */
	public void readGuardNBT(NBTTagCompound nbt) {
		if(this.getGuard() != null) {
			this.getGuard().readFromNBT(nbt.getCompoundTag("guard"));
		}
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt) {
		super.writeToNBT(nbt);

		this.writeSharedNbt(nbt);

		nbt.setInteger("version", VERSION);

		return nbt;
	}

	protected void writeSharedNbt(NBTTagCompound nbt) {
		nbt.setString("name", this.dataManager.get(NAME));
		NBTTagList boundingBoxes = new NBTTagList();
		for(AxisAlignedBB boundingBox : this.boundingBoxes) {
			boundingBoxes.appendTag(this.writeAabb(boundingBox));
		}
		nbt.setTag("bounds", boundingBoxes);
		nbt.setString("type", this.type.name);
		nbt.setInteger("layer", this.layer);
		if(this.hasAmbience()) {
			NBTTagCompound ambienceTag = new NBTTagCompound();
			this.ambience.writeToNBT(ambienceTag);
			nbt.setTag("ambience", ambienceTag);
		}
		nbt.setBoolean("visible", this.dataManager.get(VISIBLE));
		nbt.setLong("seed", this.locationSeed);
	}

	/**
	 * Writes the guard data to NBT
	 * @param nbt
	 * @return
	 */
	public NBTTagCompound writeGuardNBT(NBTTagCompound nbt) {
